        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) cout << "*";
        for (int s = 1; s <= 2 * (n - i); s++) cout << " ";
        for (int j = 1; j <= i; j++) cout << "*";
        cout << endl;
    }
    for (int i = n - 1; i >= 1; i--) {
        for (int j = 1; j <= i; j++) cout << "*";
        for (int s = 1; s <= 2 * (n - i); s++) cout << " ";
        for (int j = 1; j <= i; j++) cout << "*";
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int r, c;
    cin >> r >> c;
    char grid[16][16];
    for (int i = 1; i <= r; i++) {
        for (int j = 1; j <= c; j++) {
            grid[i][j] = ((i + j) % 2 == 0) ? 'X' : '-';
        }
    }
    for (int i = 1; i <= r; i++) {
        for (int j = 1; j <= c; j++) {
            cout << grid[i][j];
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string word;
    cin >> word;
    int len = word.length();
    for (int i = 1; i <= len; i++) {
        for (int s = 1; s <= i - 1; s++) cout << " ";
        for (int j = 0; j < i; j++) {
            cout << word[j];
        }
        cout << endl;
    }
    return 0;
}

